style.css:
/* Alterando a cor de fundo e o texto */
body {
    background-color: #282c34;
    color: white;
    font-family: 'Arial', sans-serif;
}

/* Estilizando links */
a {
    color: #ff6347;
    text-decoration: none;
}

a:hover {
    color: #ff4500;
}

/* Removendo imagens de fundo */
body {
    background-image: none !important;
}

/* Modificando título (h1) */
h1 {
    color: #FF5733;
}
